  "Add lanes to the Deck board as they become known. Each lane is a workstream that milestones and budget lanes hang off.": "Добавляйте списки на доску Deck по мере уточнения плана. Каждый список — направление работ, с которым связаны контрольные точки и статьи бюджета.",
  "Add lanes to the Deck board as they become known. Each lane is a workstream — a milestone owns cards from the lanes above it, and Budget can allocate a share to each. New Advanced projects start with only the Project management lane; add the rest here as your plan takes shape.": "Добавляйте списки на доску Deck по мере уточнения плана. Каждый список — направление работ; контрольная точка включает карточки расположенных над ней списков, а в бюджете можно выделить долю каждому направлению. В новом расширенном проекте сначала есть только список «Управление проектом»; добавляйте остальные по мере разработки плана.",
  "Add members": "Добавить участников",
