  "Advanced projects require a valid TeamHub Business license. Ask your administrator to enter one from Settings → Administration → TeamHub → License.": "Для расширенных проектов нужна действующая лицензия TeamHub Business. Попросите администратора добавить её в разделе «Настройки → Администрирование → TeamHub → Лицензия».",
