  "Aggregate counts for this Nextcloud instance. Unique team members counts every distinct person who has access to at least one team — directly, via a group, or via a sub-team — and is the metric per-seat licensing keys off.": "Сводные показатели этого сервера Nextcloud. Число уникальных участников команд учитывает каждого человека с доступом хотя бы к одной команде — напрямую, через группу или подкоманду. Этот показатель используется при лицензировании по числу пользователей.",
