  "An archive of all team data will be saved to your Files folder.": "Архив всех данных команды будет сохранён в вашей папке «Файлы».",
  "An archive of all team data will be saved to {location}.": "Архив всех данных команды будет сохранён в {location}.",
  "An archive of the collective will be produced and the collective will be permanently deleted immediately after.": "Будет создан архив коллектива, после чего коллектив немедленно удалится безвозвратно.",
  "An archive of the collective will be produced, then it will be moved to Collectives' trash for a 30-day grace period before being permanently deleted.": "Будет создан архив коллектива, после чего коллектив переместится в корзину приложения «Коллективы» на 30 дней перед окончательным удалением.",
  "An archive of the collective will be produced, then it will be moved to Collectives' trash for a 60-day grace period before being permanently deleted.": "Будет создан архив коллектива, после чего коллектив переместится в корзину приложения «Коллективы» на 60 дней перед окончательным удалением.",
  "Anchors the timeline so milestones and the health widget have a range to report against.": "Задаёт временные рамки для контрольных точек и виджета состояния.",
  "Anchors the timeline so milestones and the project-health widget have a range to report against. Both fields are optional but recommended.": "Задаёт временные рамки для контрольных точек и виджета состояния проекта. Оба поля необязательны, но рекомендуются.",
  "Anonymous usage statistics are sent daily. This instance has no active license, so telemetry is enabled.": "Анонимная статистика использования отправляется ежедневно. На этом сервере нет активной лицензии, поэтому телеметрия включена.",
  "Answer": "Ответить",
  "Answer the nine questions below to define this project. Each answer becomes part of the project's shared understanding — update them as the project evolves.": "Ответьте на девять вопросов ниже, чтобы определить проект. Каждый ответ становится частью общего понимания проекта; обновляйте ответы по мере его развития.",
