  "Checks that each team's membership cache (circles_membership) is populated. A stale/empty cache means users added via groups or other teams won't appear in share pickers for Files, Calendar, Deck, etc. Run Repair to rebuild the cache.": "Проверяет, заполнен ли кэш членства каждой команды (circles_membership). Если кэш устарел или пуст, пользователи, добавленные через группы и другие команды, не появляются в списках общего доступа «Файлов», «Календаря», Deck и других приложений. Запустите восстановление для пересоздания кэша.",
  "Checks that each team\\'s membership cache (circles_membership) is populated. A stale/empty cache means users added via groups or other teams won\\'t appear in share pickers for Files, Calendar, Deck, etc. Run Repair to rebuild the cache.": "Проверяет, заполнен ли кэш членства каждой команды (circles_membership). Если кэш устарел или пуст, пользователи, добавленные через группы и другие команды, не появляются в списках общего доступа «Файлов», «Календаря», Deck и других приложений. Запустите восстановление для пересоздания кэша.",
