  "Enable or disable third-party integrations registered by other Nextcloud apps. Widgets appear on the Home view. Tab integrations add a tab to the tab bar.": "Включайте и отключайте сторонние интеграции, зарегистрированные другими приложениями Nextcloud. Виджеты отображаются на главной странице, а интеграции вкладок добавляют вкладку на панель.",
