  "Heading": "Заголовок",
  "Heads up: any app resource connected to this team (calendar, folder, board, conversation) will be permanently deleted along with the team — even if it was created outside TeamHub. To preserve a connected resource, remove this team from its sharing permissions before deleting the team.": "Внимание: любой ресурс приложения, связанный с этой командой (календарь, папка, доска, беседа), будет безвозвратно удалён вместе с командой, даже если он создан вне TeamHub. Чтобы сохранить связанный ресурс, перед удалением команды уберите её из разрешений общего доступа к этому ресурсу.",
