  "Icon": "Значок",
  "If the estimated archive size exceeds this limit, the archiving is refused. Default: 5120 MB (5 GB).": "Если расчётный размер архива превышает это ограничение, архивирование не выполняется. По умолчанию: 5120 МБ (5 ГБ).",
  "If this colleague was just added via single sign-on (Microsoft Entra, SAML, or OIDC), they need to sign in to Nextcloud once before they can be added to a team.": "Если этот коллега только что добавлен через единый вход (Microsoft Entra, SAML или OIDC), ему нужно один раз войти в Nextcloud, прежде чем его можно будет добавить в команду.",
  "If you want a recoverable copy, ask your Nextcloud administrator to enable archiving before continuing.": "Если вам нужна копия с возможностью восстановления, попросите администратора Nextcloud включить архивирование, прежде чем продолжить.",
