  "Images inserted from personal files are copied to a hidden cache folder in the team folder so all members can view them. Clearing shows broken images in existing posts.": "Изображения, вставленные из личных файлов, копируются в скрытую папку кэша внутри папки команды, чтобы все участники могли их видеть. После очистки изображения в существующих публикациях перестанут отображаться.",
  "Images inserted from your personal files are copied into a hidden cache folder (.teamhub-cache) inside the team folder so all members can view them. Clear this cache to free up storage — existing messages will show broken images.": "Изображения, вставленные из ваших личных файлов, копируются в скрытую папку кэша (.teamhub-cache) внутри папки команды, чтобы все участники могли их видеть. Очистите кэш, чтобы освободить место, но учтите: изображения в существующих сообщениях перестанут отображаться.",
  "Impact": "Влияние",
  "In progress": "В работе",
  "In short: a member can view when their role meets the View floor OR they are an additional editor; they can edit when their role meets the Edit floor OR they are an additional editor.": "Участник может просматривать данные, если его роль соответствует минимальной роли для просмотра ИЛИ он назначен дополнительным редактором; он может редактировать данные, если его роль соответствует минимальной роли для редактирования ИЛИ он назначен дополнительным редактором.",
