  "Integrations registered by installed apps via the TeamHub API. Registration and deregistration require NC admin access and are done via the REST API or the app\\'s own settings.": "Интеграции, зарегистрированные установленными приложениями через API TeamHub. Регистрация и отмена регистрации требуют прав администратора Nextcloud и выполняются через REST API или собственные настройки приложения.",
