  "Milestone (optional)": "Контрольная точка (необязательно)",
  "Milestone reached: %s": "Контрольная точка достигнута: %s",
  "Milestone to link this proposal to": "Контрольная точка, с которой нужно связать это предложение",
  "Milestone: {label}": "Контрольная точка: {label}",
  "Milestone: {label} — {date}": "Контрольная точка: {label} — {date}",
  "Milestones": "Контрольные точки",
  "Milestones appear as a red marker line on the Timeline tab, with the label you give them. Useful for tracking key dates such as launches or deadlines at a glance.": "Контрольные точки отображаются красной линией на вкладке «Временная шкала» с указанным вами названием. Они помогают быстро отслеживать ключевые даты, например запуск или крайний срок.",
  "Milestones mark key project dates such as launches or deadlines. Every Deck card whose due date falls between a milestone and the previous one belongs to that milestone — the project-health widget uses this to flag work at risk of slipping. When Timeline is enabled, they also appear as red marker lines there.": "Контрольные точки обозначают ключевые даты проекта, например запуск или крайний срок. Каждая карточка Deck со сроком между текущей и предыдущей контрольной точкой относится к текущей точке. Виджет состояния проекта использует эту связь, чтобы отмечать работы с риском задержки. Если временная шкала включена, контрольные точки также отображаются на ней красными линиями.",
  "Milestones own the Deck cards due before them and feed the project-health widget.": "К контрольным точкам относятся карточки Deck со сроком до соответствующей точки; эти данные используются в виджете состояния проекта.",
  "Minimum member role required to pin or unpin a message. One message can be pinned per team at a time.": "Минимальная роль участника, необходимая для закрепления или открепления сообщения. В команде одновременно может быть закреплено одно сообщение.",
  "Minimum role for actions": "Минимальная роль для действий",
  "Minimum role for decision actions": "Минимальная роль для действий с решениями",
  "Minimum role required to add, edit, or delete custom links in the tab bar of this team.": "Минимальная роль, необходимая для добавления, изменения или удаления пользовательских ссылок на панели вкладок этой команды.",
  "Minimum role required to pin or unpin a message in this team. One message can be pinned at a time.": "Минимальная роль, необходимая для закрепления или открепления сообщения в этой команде. Одновременно может быть закреплено одно сообщение.",
  "Minimum role required to post new messages, questions, and polls in this team.": "Минимальная роль, необходимая для публикации новых сообщений, вопросов и опросов в этой команде.",
  "Minimum role to comment": "Минимальная роль для комментариев",
  "Minimum role to manage links": "Минимальная роль для управления ссылками",
  "Minimum role to pin": "Минимальная роль для закрепления",
