  "No milestone has open Deck cards past their due date. If any are slipping at Closing, review them in the retro.": "Ни у одной контрольной точки нет незавершённых карточек Deck с истёкшим сроком. Если на этапе завершения есть задержки, рассмотрите их в ретроспективе.",
