  "Search for a Nextcloud user to see every team they belong to and their role in each. Useful when a colleague changes jobs and you need to remove them from — or add them to — the right teams. Direct memberships can be removed from here; memberships inherited through a group or sub-team must be removed from that source.": "Найдите пользователя Nextcloud, чтобы увидеть все его команды и роль в каждой. Это полезно при смене должности коллеги, когда нужно убрать его из прежних команд или добавить в новые. Непосредственное участие можно отменить здесь; участие, унаследованное через группу или вложенную команду, нужно отменять в соответствующем источнике.",
