  "Soft delete hides the team immediately and permanently deletes it after the grace period. Administrators can restore the team before the deadline.": "Предварительное удаление сразу скрывает команду, а после льготного периода удаляет её безвозвратно. До истечения срока администраторы могут восстановить команду.",
