  "Team": "Команда",
  "Team \"{child}\" is a member of this team, but has \"Prevent from being a member of another team\" enabled — remove the membership or update {child}'s settings.": "Команда «{child}» входит в эту команду, но для неё включён запрет участия в другой команде. Удалите связь участия или измените настройки {child}.",
