  "Team timeline": "Временная шкала команды",
  "Team admins can invite people from outside this server by email or federated Nextcloud account. Change this on the Team creation tab under Allowed invite types.": "Администраторы команд могут приглашать людей за пределами этого сервера по электронной почте или через учётную запись другого сервера Nextcloud. Измените это на вкладке «Создание команд» в разделе «Разрешённые типы приглашений».",
