  "Team name is too long (max 120 characters).": "Название команды слишком длинное (не более 120 символов).",
  "Team navigation": "Навигация команды",
  "Team pages will be created at: IntraVox / {path} / team-name": "Страницы команд будут созданы по адресу: IntraVox / {path} / team-name",
  "Team presence — week view": "Присутствие команды — неделя",
  "Team removed": "Команда удалена",
