  "Time settings saved": "Настройки учёта времени сохранены",
  "Time to wrap up. Tie off loose ends, evaluate the project with your team, and archive it once everything is settled.": "Пора завершать. Закройте оставшиеся вопросы, оцените проект вместе с командой и архивируйте его, когда всё будет улажено.",
  "Time to wrap up. Tie off loose ends, evaluate the project with your team, and archive it once everything is settled. Dedicated closing tools are coming in a future update.": "Пора завершать. Закройте оставшиеся вопросы, оцените проект вместе с командой и архивируйте его, когда всё будет улажено. Специальные инструменты завершения появятся в будущем обновлении.",
