  "Timeline": "Временная шкала",
  "Timeline is disabled for this team — milestones you add here still drive the project-health widget, but will not appear on the Timeline tab until Timeline is enabled under Integration Settings.": "Временная шкала отключена для этой команды. Добавленные здесь контрольные точки по-прежнему используются в виджете состояния проекта, но появятся на вкладке временной шкалы только после её включения в настройках интеграций.",
  "Timeline is disabled for this team. Enable it under the Integrations tab to manage milestones.": "Временная шкала отключена для этой команды. Включите её на вкладке «Интеграции», чтобы управлять контрольными точками.",
