  "User ID": "Идентификатор пользователя",
  "User identifiers will be replaced with aliases in the archive (pseudonymized per organisation policy).": "Идентификаторы пользователей в архиве будут заменены псевдонимами согласно политике организации.",
  "Users can pick this themselves": "Пользователи могут выбирать это самостоятельно",
  "Users of the end result": "Пользователи конечного результата",
  "Utilisation": "Использование",
  "Verifies shipped files against a SHA-256 manifest generated at build time.": "Проверяет поставляемые файлы по манифесту SHA-256, созданному во время сборки.",
  "Verifies that the installed TeamHub code matches the released build. A SHA-256 manifest generated at build time is compared against the files on disk. Use this to detect unauthorised changes or a corrupted install.": "Проверяет соответствие установленного кода TeamHub выпущенной сборке. Манифест SHA-256, созданный во время сборки, сравнивается с файлами на диске. Используйте проверку для обнаружения несанкционированных изменений или повреждения установки.",
  "Verifying code integrity…": "Проверка целостности кода…",
