  "You are no longer a direct member, but you still have access to this team through a group or another team.": "Вы больше не являетесь непосредственным участником, но по-прежнему имеете доступ к команде через группу или другую команду.",
  "You are not an approver for this decision.": "Вы не являетесь согласующим этого решения.",
