  "You are not a member of any team.": "Вы не состоите ни в одной команде.",
  "You can disable this message by unchecking “Getting started” under Personal settings → TeamHub.": "Это сообщение можно отключить, сняв флажок «Начало работы» в личных настройках → TeamHub.",
  "You can grow to {lockAt} users before Advanced-team creation and writes lock. Upgrade the license or reduce unique team members.": "Число пользователей может вырасти до {lockAt}, прежде чем создание команд Advanced и изменение данных будут заблокированы. Обновите лицензию или уменьшите число уникальных участников команд.",
  "You can rearrange the team’s tabs from the tab bar on its home page.": "Порядок вкладок команды можно изменить на панели вкладок её главной страницы.",
  "You can retry below. The previous failed attempt will be cleared automatically.": "Повторите попытку ниже. Сведения о предыдущей неудачной попытке будут очищены автоматически.",
  "You denied this decision": "Вы отклонили это решение",
