  "a single project-level role. A member sees the Budget tab when their team role is at or above this level. Any member who is a named additional editor on ANY workstream also automatically sees the tab, regardless of their role.": "единая роль на уровне проекта. Участник видит вкладку «Бюджет», если его роль в команде соответствует этому уровню или выше. Любой участник, назначенный дополнительным редактором ХОТЯ БЫ ОДНОГО направления работ, также автоматически видит вкладку независимо от своей роли.",
