  "Minimum role to manage posts": "Минимальная роль для управления публикациями",
  "Who can pin a message, and edit or delete a message or comment written by someone else. Authors can always edit and delete their own. Every edit is shown under the post with who made it.": "Кто может закреплять сообщения, а также изменять или удалять чужие сообщения и комментарии. Авторы всегда могут изменять и удалять свои публикации. Под каждой изменённой публикацией указано, кто её изменил.",
  "Edited by {name} on {datetime}": "Изменено: {name}, {datetime}",
  "Tags": "Метки",
  "Classify this team with the same Nextcloud tags you use on files. An administrator manages the available tags under Settings → Administration → Basic settings.": "Классифицируйте команду с помощью тех же меток Nextcloud, которые используются для файлов. Администратор управляет доступными метками в разделе «Настройки» → «Администрирование» → «Основные настройки».",
  "Remove tag {tag}": "Удалить метку {tag}",
  "This team has no tags yet.": "У этой команды пока нет меток.",
