  "Failed to remove tag: {error}": "Не удалось удалить метку: {error}",
  "Failed to remove tag": "Не удалось удалить метку",
  "Team classification": "Классификация команд",
  "Team classification details": "Подробности классификации команд",
  "Classification:": "Классификация:",
  "No teams tagged": "Нет команд с метками",
  "{tagged} of {total} tagged": "С метками: {tagged} из {total}",
  "Teams carrying at least one Nextcloud tag. Tags are managed under Settings → Administration → Basic settings, and a team admin applies them in Manage Team.": "Команды хотя бы с одной меткой Nextcloud. Метки настраиваются в разделе «Настройки» → «Администрирование» → «Основные настройки», а администратор команды назначает их в управлении командой.",
  "ISO 27001: {controls}": "ISO 27001: {controls}",
  "Audit log retention": "Срок хранения журнала аудита",
  "Audit log retention details": "Подробности хранения журнала аудита",
  "Audit log:": "Журнал аудита:",
  "Events are appended and purged in bulk after the retention window. No code path updates or deletes an individual row, so a record cannot be rewritten before it expires.": "События добавляются в журнал и массово удаляются по истечении срока хранения. Код не изменяет и не удаляет отдельные строки, поэтому запись нельзя переписать до истечения её срока.",
  "{n} day retention": [
    "Срок хранения: {n} дн.",
    "Срок хранения: {n} дн.",
    "Срок хранения: {n} дн.",
    "Срок хранения: {n} дн."
  ],
  "No teams": "Нет команд",
  "Only a Nextcloud administrator can change this tag": "Только администратор Nextcloud может изменить эту метку",
  "\"{name}\" will be removed. No team is using it, so nothing else changes.": "«{name}» будет удалено. Ни одна команда его не использует, поэтому больше ничего не изменится.",
  "A classification profile decides what a team's settings are set to. Some settings only TeamHub can change, so a locked value is genuinely refused. Others belong to Nextcloud Teams or to the app itself and can be changed from Contacts, the Teams app, or Deck and Talk directly — for those, TeamHub sets the value and reports any later change, but cannot prevent one.": "Профиль классификации задаёт значения настроек команды. Некоторые настройки может изменять только TeamHub, поэтому изменение заблокированного значения действительно запрещается. Другие принадлежат командам Nextcloud или самому приложению и могут изменяться через «Контакты», приложение команд, Deck или Talk. Для них TeamHub устанавливает значение и сообщает о последующих изменениях, но не может предотвратить их.",
  "A setting you leave switched off is not governed at all — the profile says nothing about it, which is different from setting it to off.": "Если вы не включили управление настройкой, профиль её совсем не регулирует. Это отличается от назначения ей значения «отключено».",
  "A template decides what a new team is created with: its apps, its modules, and whether the team creation form offers an expiration date.": "Шаблон определяет, с чем создаётся новая команда: её приложения, модули и наличие поля срока действия в форме создания.",
  "Allowed": "Разрешено",
  "Applied when the profile is applied. A team administrator may change it afterwards.": "Применяется вместе с профилем. После этого администратор команды может изменить значение.",
  "Applied, and afterwards a team administrator may not change it.": "Применяется, и после этого администратор команды не может изменить значение.",
  "Apps created with the team": "Приложения, создаваемые вместе с командой",
  "Cannot be a member of another team": "Не может участвовать в другой команде",
  "Classification profiles": "Профили классификации",
  "Confidential": "Конфиденциально",
  "Contacts, the Teams app or the app itself can also change this. TeamHub sets it, keeps its own screens read-only, and reports any later change — it cannot prevent one.": "Это также можно изменить в «Контактах», приложении команд или самом приложении. TeamHub устанавливает значение, запрещает его редактирование в своих формах и сообщает о последующих изменениях, но не может предотвратить их.",
  "Could not delete the profile.": "Не удалось удалить профиль.",
  "Could not load policy settings.": "Не удалось загрузить настройки политик.",
  "Could not open that profile.": "Не удалось открыть этот профиль.",
  "Could not save the profile.": "Не удалось сохранить профиль.",
  "Could not save the template.": "Не удалось сохранить шаблон.",
