  "Delete this profile?": "Удалить этот профиль?",
  "Edit profile": "Изменить профиль",
  "Edit template": "Изменить шаблон",
  "Editing a template here does not change team creation yet. The team creation form still uses the values built into this version.": "Изменение шаблона здесь пока не влияет на создание команд. Форма создания по-прежнему использует значения, встроенные в эту версию.",
  "Enforced": "Принудительно задано",
