  "Lower numbers are less sensitive and appear first.": "Меньшие значения означают меньшую чувствительность и отображаются первыми.",
  "Lowercase letters, digits and underscores. This is how the profile is identified and it cannot be changed later.": "Строчные латинские буквы, цифры и знаки подчёркивания. Это идентификатор профиля; впоследствии изменить его нельзя.",
