  "Templates and profiles that disagree": "Шаблоны и профили с противоречиями",
  "Templates, in the order they appear when creating a team.": "Шаблоны в порядке отображения при создании команды.",
  "The profile always wins, so a team created from one of these pairs is still correct — it simply does not get everything the template offers. Change one side if that is not what you meant.": "Профиль всегда имеет приоритет, поэтому команда, созданная из одной из этих пар, всё равно настроена правильно, но получает не всё, что предлагает шаблон. Если это не соответствует замыслу, измените шаблон или профиль.",
