  "Profiles": "Профили",
  "Team expiration": "Срок действия команды",
  "The date the picker opens on when someone creates this kind of team. 0 leaves it on the standard six months.": "Дата, на которой открывается календарь при создании команды этого типа. При значении 0 используется стандартный срок в шесть месяцев.",
