  "Could not change what new teams get.": "Не удалось изменить настройки новых команд.",
  "Leave empty for a team with no end date. If you set one, the team keeps working after it passes — nothing is deleted — but its administrators and a Nextcloud administrator are reminded a week beforehand, and the date can be extended at any time.": "Оставьте пустым для команды без срока действия. Если задать дату, по её истечении команда продолжит работать и ничего не будет удалено. За неделю до неё администраторы команды и администратор Nextcloud получат напоминание. Срок можно продлить в любое время.",
  "New teams will be classified as {name}.": "Новым командам будет назначена классификация {name}.",
