  "A group cannot own a team, so Team owner is unavailable for groups.": "Группа не может владеть командой, поэтому роль владельца для групп недоступна.",
  "Description shown when creating a team": "Описание при создании команды",
  "Explain what this policy means for the team — who can find it, who can join, what is shared.": "Объясните, что эта политика означает для команды: кто может найти её, кто может вступить и к чему предоставляется общий доступ.",
