  "This replaces the profile the team carries now.": "Это заменит текущий профиль команды.",
  "Remove the profile": "Удалить профиль",
  "The team keeps its current settings and stops being checked against a profile.": "Команда сохранит текущие настройки и больше не будет проверяться на соответствие профилю.",
  "Apply the profile": "Применить профиль",
