  "Complete the review of “{title}”?": "Завершить проверку «{title}»?",
  "This file is not in one of your team folders, so a review cannot be requested for it.": "Этот файл находится вне папок ваших команд, поэтому запросить его проверку нельзя.",
  "Reviewers": "Проверяющие",
