  "What would you like them to look at?": "На что им следует обратить внимание?",
  "The review could not be requested.": "Не удалось запросить проверку.",
  "This file could not be checked. Try again.": "Не удалось проверить этот файл. Повторите попытку.",
  "File reviews": "Проверки файлов",
  "Enable file reviews for all teams": "Включить проверки файлов для всех команд",
