  "The OpenProject widgets disappear from this team's home for every member, and the quick actions with them.": "Виджеты OpenProject и связанные с ними быстрые действия исчезнут с главной страницы команды для всех участников.",
  "Nothing changes in OpenProject: the project, its work packages and its files stay exactly as they are. You can link the project again at any time.": "В OpenProject ничего не изменится: проект, его рабочие пакеты и файлы останутся как есть. Проект можно снова связать в любое время.",
