  "Every member of this team gets the project overview and their own work packages on the team home. The project must already exist in OpenProject.": "Каждый участник команды получит обзор проекта и собственные рабочие пакеты на главной странице команды. Проект уже должен существовать в OpenProject.",
  "Linking OpenProject project": "Связывание проекта OpenProject",
  "OpenProject: {name}": "OpenProject: {name}",
  "That OpenProject project is already linked to another team.": "Этот проект OpenProject уже связан с другой командой.",
  "The team was created, but its OpenProject project could not be linked: {error}": "Команда создана, но связать проект OpenProject не удалось: {error}",
  "Created from the OpenProject project template.": "Создано из шаблона проекта OpenProject.",
  "Only projects you administer in OpenProject, or public projects, are listed. A project can be linked to one team.": "Показаны только общедоступные проекты и проекты, которыми вы управляете в OpenProject. Проект можно связать с одной командой.",
  "You administer this project": "Вы управляете этим проектом",
  "The OpenProject project this team was created for. It was chosen when the team was created and cannot be changed here; the project itself is managed in OpenProject.": "Проект OpenProject, для которого создана эта команда. Он выбран при создании команды и не может быть изменён здесь; самим проектом управляют в OpenProject.",
  "Edit blueprint": "Изменить схему",
  "Blueprint for {template}": "Схема для {template}",
  "The blueprint decides what a workspace of this kind is made of on the Nextcloud side: required and optional applications, the dashboard, whether an OpenProject project is needed and which OpenProject templates may seed one, and how TeamHub roles map to OpenProject roles. What is inside the OpenProject project — work-package types, milestones, phases — is the OpenProject template's.": "Схема определяет состав рабочего пространства этого типа со стороны Nextcloud: обязательные и необязательные приложения, панель управления, необходимость проекта OpenProject, допустимые шаблоны для его создания и сопоставление ролей TeamHub с ролями OpenProject. Содержимое проекта OpenProject — типы рабочих пакетов, контрольные точки и этапы — определяется шаблоном OpenProject.",
  "This template has no stored blueprint yet; what is shown is derived from its apps and modules. Saving stores it.": "У этого шаблона ещё нет сохранённой схемы; показанные значения получены из его приложений и модулей. При сохранении схема будет записана.",
  "Applications": "Приложения",
  "Application": "Приложение",
  "{component} required": "{component} обязательно",
  "{component} optional": "{component} необязательно",
  "Module": "Модуль",
