  "Dashboard widgets shown": "Показываемые виджеты панели управления",
  "Widgets for applications the workspace does not have are hidden anyway. Leave every box unticked to hide nothing else.": "Виджеты приложений, которых нет в рабочем пространстве, в любом случае скрываются. Не отмечайте ни одного флажка, чтобы не скрывать ничего дополнительно.",
  "May create a new project": "Можно создавать новый проект",
  "May connect an existing project": "Можно подключать существующий проект",
  "May choose a parent project": "Можно выбирать родительский проект",
  "Approved OpenProject templates": "Одобренные шаблоны OpenProject",
  "Only these templates are offered when a new project is created. None ticked means every template the creator may copy.": "При создании проекта предлагаются только эти шаблоны. Если ничего не отмечено, предлагаются все шаблоны, которые создатель может копировать.",
  "No OpenProject template is available to your account.": "Вашей учётной записи не доступен ни один шаблон OpenProject.",
  "Approved template #{id} ({name}) is not visible to your account; it stays approved.": "Одобренный шаблон №{id} ({name}) недоступен вашей учётной записи; он остаётся одобренным.",
  "Role mapping": "Сопоставление ролей",
  "The OpenProject role each TeamHub role gets when a workspace is created. Memberships are created as the person creating the workspace, so OpenProject applies its own rules on top.": "Роль OpenProject, назначаемая каждой роли TeamHub при создании рабочего пространства. Участие назначается от имени создателя пространства, поэтому дополнительно действуют собственные правила OpenProject.",
