  "Visibility in OpenProject": "Видимость в OpenProject",
  "Who may see the team in TeamHub is the policy's setting; this is the OpenProject project's own visibility, applied when a new project is created.": "Видимость команды в TeamHub определяется политикой; здесь задаётся собственная видимость проекта OpenProject, применяемая при создании проекта.",
  "Asking OpenProject what is available to you": "Запрос доступных вам возможностей OpenProject",
