  "These parts may already hold content: {parts}. Remove the team and everything created for it? The OpenProject project is never deleted by TeamHub.": "В этих частях уже может быть содержимое: {parts}. Удалить команду и всё созданное для неё? TeamHub никогда не удаляет сам проект OpenProject.",
