  "Lowercase letters, digits, dashes and underscores. It becomes part of the project address in OpenProject and cannot be changed later.": "Строчные латинские буквы, цифры, дефисы и знаки подчёркивания. Идентификатор станет частью адреса проекта в OpenProject; впоследствии изменить его нельзя.",
  "OpenProject template": "Шаблон OpenProject",
