  "Everything TeamHub will create or link for this workspace. Nothing happens until you confirm.": "Всё, что TeamHub создаст или подключит для этого пространства. До вашего подтверждения ничего не произойдёт.",
  "Project basics": "Основные сведения о проекте",
  "Instance default": "По умолчанию для экземпляра",
  "Visibility": "Видимость",
  "Public project in OpenProject": "Общедоступный проект в OpenProject",
  "Private project in OpenProject": "Закрытый проект в OpenProject",
  "Resources": "Ресурсы",
  "Only you. You can invite people later.": "Только вы. Пригласить людей можно позже.",
  "{name} becomes the owner of the team once everything is set up.": "{name} станет владельцем команды после завершения настройки.",
  "OpenProject did not accept this.": "OpenProject отклонил это.",
  "OpenProject could not finish copying the template.": "OpenProject не смог завершить копирование шаблона.",
  "Blueprint": "Схема",
  "OpenProject workspace": "Рабочее пространство OpenProject",
  "How a workspace of this kind is built around its OpenProject project. The apps and modules above decide what the team is connected to; this decides the project, the roles, the files and the dashboard. What is inside the OpenProject project — work-package types, milestones, phases — is the OpenProject template's.": "Как пространство этого типа строится вокруг проекта OpenProject. Приложения и модули выше определяют подключённые ресурсы; здесь задаются проект, роли, файлы и панель управления. Содержимое проекта OpenProject — типы рабочих пакетов, контрольные точки и этапы — определяется шаблоном OpenProject.",
  "The project folder OpenProject manages is OpenProject's: linked, never created or changed by TeamHub. The team folder is the team's.": "Папкой проекта управляет OpenProject: TeamHub только связывает её и никогда не создаёт и не изменяет. Папка команды принадлежит команде.",
  "Hands the team over and leaves it and the project": "Передаёт команду и покидает её и проект",
  "Hands the team over and leaves it; keeps the project access they already have": "Передаёт команду и покидает её; сохраняет уже имеющийся доступ к проекту",
  "By project": "По проектам",
  "By team": "По командам",
  "Due soon": "Срок скоро",
  "Due today": "Срок сегодня",
  "Some {source} projects could not be read. The rows shown are complete for the projects that answered.": "Некоторые проекты {source} не удалось прочитать. Для ответивших проектов показаны все строки.",
  "Upcoming milestone": "Предстоящая контрольная точка",
  "Updated recently": "Недавно обновлено",
  "{source} answered slowly, so not every project was read this time. Refresh to try again.": "{source} отвечал медленно, поэтому не все проекты прочитаны в этот раз. Обновите для повторной попытки.",
  "{source} no longer accepts your connection. Reconnect your account in your personal settings.": "{source} больше не принимает ваше подключение. Подключите учётную запись заново в личных настройках.",
