  "Workflow: step {current} of {total}": "Процесс: шаг {current} из {total}",
  "{actor}, {date}": "{actor}, {date}",
  "A reason is required.": "Укажите причину.",
  "Granted. The team space of %1$s now holds %2$s; the team admins have been told.": "Предоставлено. Теперь пространство команды %1$s вмещает %2$s; администраторы команды уведомлены.",
  "Declined. The team admins have been told, with your reason.": "Отказано. Администраторы команды уведомлены с указанием вашей причины.",
  "no quota": "без квоты",
  "%1$s asks for %2$s (now %3$s): %4$s": "%1$s запрашивает %2$s (сейчас %3$s): %4$s",
  "%1$s asks for %2$s (now %3$s).": "%1$s запрашивает %2$s (сейчас %3$s).",
  "Grant %1$s to %2$s?": "Предоставить %1$s команде %2$s?",
  "The team space quota is set to %s right away, and the team admins are told, with your reason.": "Квота пространства команды сразу станет %s, а администраторы команды получат уведомление с вашей причиной.",
  "Reason (shown to the team admins)": "Причина (видна администраторам команды)",
  "Decline the request of %s?": "Отклонить запрос %s?",
  "The quota stays at %s, and the team admins are told, with your reason.": "Квота останется %s, а администраторы команды получат уведомление с вашей причиной.",
  "%1$s granted %2$s: %3$s — waiting for the team admin to close it.": "%1$s предоставил(а) %2$s: %3$s — ожидается закрытие администратором команды.",
  "%1$s declined: %2$s — waiting for the team admin to close it.": "%1$s отказал(а): %2$s — ожидается закрытие администратором команды.",
  "Closed by the team admin. Decision: %s": "Закрыто администратором команды. Решение: %s",
