  "Closed. The request is filed under Completed.": "Закрыто. Запрос перемещён в завершённые.",
  "%1$s granted %2$s: %3$s": "%1$s предоставил(а) %2$s: %3$s",
  "%1$s declined: %2$s": "%1$s отказал(а): %2$s",
  "Closed. Decision by %1$s: %2$s": "Закрыто. Решение от %1$s: %2$s",
  "Asked by %1$s. A Nextcloud administrator grants or declines it; you are notified either way.": "Запрос от %1$s. Администратор Nextcloud одобрит его или откажет; вы получите уведомление в любом случае.",
  "Team space quota increase to %s": "Увеличение квоты пространства команды до %s",
  "Close the quota request?": "Закрыть запрос квоты?",
  "The request is filed under Completed for you and the administrators. The quota stays as decided.": "Запрос будет перемещён в завершённые у вас и администраторов. Квота останется согласно решению.",
  "A team admin": "Администратор команды",
  "{team} asks for a team space of {size}": "{team} запрашивает пространство команды размером {size}",
  "%1$s (now %2$s): %3$s. Grant or decline it in My Work → Administration.": "%1$s (сейчас %2$s): %3$s. Одобрите или отклоните в разделе «Моя работа» → «Администрирование».",
  "%1$s (now %2$s). Grant or decline it in My Work → Administration.": "%1$s (сейчас %2$s). Одобрите или отклоните в разделе «Моя работа» → «Администрирование».",
  "{admin} granted {team} a team space of {size}": "{admin} предоставил(а) команде {team} пространство размером {size}",
  "{admin} declined the team space request of {team}": "{admin} отклонил(а) запрос пространства команды {team}",
  "%1$s granted %2$s a team space of %3$s": "%1$s предоставил(а) команде %2$s пространство размером %3$s",
  "%1$s declined the team space request of %2$s": "%1$s отклонил(а) запрос пространства команды %2$s",
  "Reason: %s": "Причина: %s",
  "Telling people apart": "Как различать людей с одинаковыми именами",
  "When two people share a name, the line under the name in every search result says which one it is. Choose the profile fields that line is built from; the first two that are filled in are shown, in this order. A field a person set to private on their profile is only shown to administrators.": "Если у двух людей одинаковое имя, строка под именем в результатах поиска помогает различить их. Выберите поля профиля для этой строки: показываются первые два заполненных поля в указанном порядке. Поле, которое человек сделал закрытым в профиле, видно только администраторам.",
  "No field is selected: search results show the name only.": "Поля не выбраны: в результатах поиска показывается только имя.",
