  "Email address": "Адрес электронной почты",
  "From the profile — \"Controller\", \"Team lead\"": "Из профиля — «Контролёр», «Руководитель команды»",
  "From the profile — the company or the department, whichever the profile holds": "Из профиля — компания или подразделение, в зависимости от содержимого профиля",
