  "The manager set on the account, by name": "Имя руководителя, указанного для учётной записи",
  "Up to three of the groups the person is in — in many directories these are the departments. Visible to everyone who can search": "До трёх групп пользователя — во многих каталогах это подразделения. Видно всем, кому доступен поиск",
  "The account email address": "Адрес электронной почты учётной записи",
  "The account name used to log in": "Имя учётной записи для входа",
  "Close the request in My Work → Team admin.": "Закройте запрос в разделе «Моя работа» → «Администрирование команды».",
  "There is no workflow of that kind.": "Процесса такого типа нет.",
  "A team and a user are required.": "Необходимо указать команду и пользователя.",
  "You cannot start this workflow on this team.": "Вы не можете запустить этот процесс для этой команды.",
