  "Show all work": "Показать все работы",
  "Show only one type of work": "Показать только один тип работ",
  "A service team answers requests from the rest of the organisation. Pick a team that already exists, say who owns the service and who works its queue, then open it for requests.": "Обслуживающая команда обрабатывает заявки остальных подразделений организации. Выберите существующую команду, укажите владельца услуги и исполнителей очереди, затем откройте приём заявок.",
  "Add internal note": "Добавить внутреннее примечание",
  "Agent": "Исполнитель",
  "An existing team. Nothing is created here — this declares which team answers requests.": "Существующая команда. Здесь ничего не создаётся — только определяется команда, отвечающая на заявки.",
  "Answerable for the service. Always able to work the queue, assign work and change the catalogue.": "Ответственный за услугу. Всегда может работать с очередью, назначать работу и изменять каталог.",
