  "Open for requests": "Приём заявок открыт",
  "Pick the team that will answer requests.": "Выберите команду, которая будет обрабатывать заявки.",
  "Pick what you need. An agent picks the request up, answers it, and you confirm when it is done.": "Выберите нужную услугу. Исполнитель возьмёт заявку в работу и ответит, а вы подтвердите выполнение.",
