  "Found": "Найдено",
  "Asked": "Запрошено",
  "Added": "Добавлено",
  "New teams": "Новые команды",
  "No policy": "Без политики",
  "No teams are waiting": "Нет ожидающих команд",
  "Teams made in Contacts, on the Teams page or by a provisioning tool appear here within a few minutes.": "Команды, созданные в «Контактах», на странице команд или средствами автоматического создания, появляются здесь в течение нескольких минут.",
  "Teams waiting for a decision": "Команды, ожидающие решения",
  "Template for {team}": "Шаблон для {team}",
  "Policy for {team}": "Политика для {team}",
  "Handled by {name}": "Обработано: {name}",
  "Accepting shows the team in TeamHub at once and locks it against deletion from the Teams page. The template's apps are added within a few minutes, in the name of the team owner. A declined team stays as it is in Nextcloud and is not offered again.": "При принятии команда сразу появляется в TeamHub и защищается от удаления со страницы команд. Приложения шаблона добавляются в течение нескольких минут от имени владельца команды. Отклонённая команда остаётся в Nextcloud без изменений и больше не предлагается.",
  "Decided in the last 30 days": "Решения за последние 30 дней",
  "Decline {team}": "Отклонить {team}",
  "The team stays as it is in Nextcloud, but it is not shown in TeamHub and is not offered again. The owner is told why.": "Команда останется в Nextcloud без изменений, но не будет показываться в TeamHub и предлагаться повторно. Владелец получит объяснение причины.",
  "Decline team": "Отклонить команду",
  "Could not load the teams made outside TeamHub.": "Не удалось загрузить команды, созданные вне TeamHub.",
  "Could not save the choice.": "Не удалось сохранить выбор.",
  "{team} added to TeamHub": "{team} добавлена в TeamHub",
  "Could not accept the team.": "Не удалось принять команду.",
  "{team} declined": "{team} — отклонено",
  "Could not decline the team.": "Не удалось отклонить команду.",
  "Administrators in My Work": "Администраторы в разделе «Моя работа»",
  "Accepted by itself": "Принято автоматически",
  "This list": "Этот список",
  "Needs a hand": "Нужна помощь",
  "Being added": "Добавление",
  "Teams made outside TeamHub": "Команды, созданные вне TeamHub",
  "Teams made in Contacts, on the Teams page or by a provisioning tool are not in TeamHub until they are accepted here, with a template and a policy. Without a team creator group they are accepted by themselves; when a team holds the Nextcloud services, its members decide too.": "Команды, созданные в «Контактах», на странице команд или средствами автоматического создания, не попадают в TeamHub до принятия здесь с шаблоном и политикой. Если группа создателей команд не задана, они принимаются автоматически; если команда предоставляет услуги Nextcloud, её участники тоже могут принимать решения.",
  "Accept teams made outside TeamHub": "Принимать команды, созданные вне TeamHub",
  "Decide whether a team made in Contacts, on the Teams page or by a provisioning tool joins TeamHub, and with which template and policy.": "Решайте, включать ли в TeamHub команды, созданные в «Контактах», на странице команд или средствами автоматического создания, и какие шаблон и политику им назначить.",
  "Accept team \"%s\" into TeamHub": "Принять команду «%s» в TeamHub",
  "This team was made outside TeamHub. Accept it to show it in TeamHub with a template and a policy, or decline it to leave it out.": "Эта команда создана вне TeamHub. Примите её, назначив шаблон и политику, чтобы показывать в TeamHub, либо отклоните, чтобы оставить вне него.",
  "Team found": "Команда найдена",
  "Team accepted or declined": "Команда принята или отклонена",
  "Choose template and policy in the team grid": "Выберите шаблон и политику в таблице команд",
  "This team is no longer waiting for a decision.": "Эта команда больше не ожидает решения.",
  "This team is not waiting for a decision.": "Эта команда не ожидает решения.",
  "This team no longer exists in Nextcloud.": "Эта команда больше не существует в Nextcloud.",
  "The team was added to TeamHub another way.": "Команда добавлена в TeamHub другим способом.",
  "Accepted by a Nextcloud administrator in Admin → TeamHub.": "Принято администратором Nextcloud в разделе «Администрирование» → TeamHub.",
