  "The service team is waiting for your answer. What you send now answers their question.": "Обслуживающая команда ожидает вашего ответа. Следующее сообщение станет ответом на её вопрос.",
  "Wait for the requester's answer": "Ожидать ответа заявителя",
  "The request shows as waiting until the requester answers.": "Заявка будет отмечена как ожидающая, пока заявитель не ответит.",
  "Send answer": "Отправить ответ",
  "Ask the requester": "Спросить заявителя",
  "Send message": "Отправить сообщение",
  "This request is closed. The conversation stays with it.": "Эта заявка закрыта. Переписка сохраняется вместе с ней.",
  "Claim the request to write to the requester.": "Возьмите заявку в работу, чтобы написать заявителю.",
  "Only the team member who claimed the request writes to the requester.": "Писать заявителю может только участник команды, взявший заявку в работу.",
