  "Public decision": "Общедоступное решение",
  "Team decision": "Решение команды",
  "Everybody signed in on this Nextcloud can read this decision and find it in a search. Only this team can act on it.": "Любой вошедший пользователь этого Nextcloud может прочитать это решение и найти его через поиск. Выполнять действия с ним может только эта команда.",
  "Only this team can read this decision. Make it public to let everybody signed in on this Nextcloud read it and find it in a search.": "Только эта команда может читать решение. Сделайте его общедоступным, чтобы любой вошедший пользователь этого Nextcloud мог прочитать его и найти через поиск.",
  "Decision published": "Решение опубликовано",
  "Decision is team only again": "Решение снова доступно только команде",
  "Failed to change who can read this decision: {error}": "Не удалось изменить доступ к чтению решения: {error}",
