  "{question} — {status}": "{question} — {status}",
  "A decision of this team": "Решение этой команды",
  "Took a linked decision off this request.": "Связанное решение удалено из этой заявки.",
  "Linked the decision behind this request.": "Связано решение, на котором основана эта заявка.",
  "Decision removed": "Решение удалено",
  "Post a decision of this service team into the conversation. Only approved, published decisions can be linked — the requester reads this too.": "Опубликуйте решение этой обслуживающей команды в беседе. Можно связывать только согласованные и опубликованные решения — заявитель тоже читает их.",
  "No approved, published decision of this team matches those words.": "Согласованные опубликованные решения этой команды по этим словам не найдены.",
  "Only the four most recent matches are shown. Add a word to narrow them.": "Показаны только четыре последних совпадения. Добавьте слово, чтобы сузить поиск.",
  "Back to requests": "Вернуться к заявкам",
  "Back to My Work": "Вернуться в раздел «Моя работа»",
  "Back to catalog": "Вернуться в каталог",
