  "Only an approved decision can be linked to a request.": "С заявкой можно связать только согласованное решение.",
  "Publish the decision first. The requester reads this conversation, and only a public decision opens for them.": "Сначала опубликуйте решение. Заявитель читает эту беседу, и ему доступно только общедоступное решение.",
