  "It appears on your My Work page and nobody else’s.": "Она появится только на вашей странице «Моя работа».",
  "It appears on their My Work page and they are notified. You can follow it under Waiting for others.": "Она появится на странице «Моя работа» исполнителя, и он получит уведомление. Вы можете следить за ней в разделе «Ожидание других».",
  "My task": "Моя задача",
