  "Team task": "Задача команды",
  "Approved decisions": "Согласованные решения",
  "Archive decision": "Архивировать решение",
  "Archive this decision? It moves to the team archive and becomes read-only. The record and its audit trail are kept.": "Архивировать это решение? Оно переместится в архив команды и станет доступно только для чтения. Запись и история аудита сохранятся.",
  "Archive this decision?": "Архивировать это решение?",
  "It moves to the team archive and becomes read-only. The record and its audit trail are kept.": "Оно переместится в архив команды и станет доступно только для чтения. Запись и история аудита сохранятся.",
  "Keep this decision?": "Сохранить действие этого решения?",
  "The decision stays in force and its review period starts again from today.": "Решение останется в силе, а срок пересмотра начнётся заново с сегодняшнего дня.",
  "Note for the record (optional)": "Примечание для истории (необязательно)",
  "Archived after review": "Архивировано после пересмотра",
  "Archived from {category}": "Архивировано из категории {category}",
  "Archived {date}": "Архивировано {date}",
  "Could not complete the review": "Не удалось завершить пересмотр",
  "Could not load the approved decisions": "Не удалось загрузить согласованные решения",
  "Could not request a review": "Не удалось запросить пересмотр",
  "Could not supersede this decision": "Не удалось заменить это решение новым",
  "Decision archived": "Решение архивировано",
  "Decision archived.": "Решение архивировано.",
  "Decision superseded and moved to the archive": "Решение заменено новым и перемещено в архив",
  "Describe what changed — this becomes part of the audit trail.": "Опишите изменения — это станет частью истории аудита.",
  "Keep decision": "Сохранить действие решения",
  "Kept after review": "Оставлено в силе после пересмотра",
  "Moved to archive": "Перемещено в архив",
  "Next review due {date}": "Следующий пересмотр: {date}",
  "No archived decisions": "Нет архивных решений",
  "No superseded decisions": "Нет заменённых решений",
  "Pick the decision that overrules this one. This decision moves to the archive and becomes read-only.": "Выберите решение, отменяющее это. Текущее решение переместится в архив и станет доступно только для чтения.",
  "Request a review": "Запросить пересмотр",
  "Review completed. The decision stands.": "Пересмотр завершён. Решение остаётся в силе.",
  "Review date reached": "Наступила дата пересмотра",
  "Review requested": "Пересмотр запрошен",
  "Review requested. The approvers have it in My Work.": "Пересмотр запрошен. Согласующие увидят его в разделе «Моя работа».",
  "Submitting": "Отправка",
  "Superseded": "Заменено новым решением",
  "Superseded by: {question}": "Заменено решением: {question}",
  "The approvers of this category will be asked to look at the decision again. It stays in force until they answer.": "Согласующим этой категории будет предложено рассмотреть решение ещё раз. До их ответа оно остаётся в силе.",
  "This decision has been archived and is read-only.": "Это решение архивировано и доступно только для чтения.",
  "This decision has been superseded and is read-only.": "Это решение заменено новым и доступно только для чтения.",
  "This decision has reached its review date. It stays in force until the approvers answer.": "Наступила дата пересмотра этого решения. Оно остаётся в силе до ответа согласующих.",
  "This decision has reached its review date": "Наступила дата пересмотра этого решения",
  "This team has no other approved decision to supersede this one with.": "У этой команды нет другого согласованного решения для замены текущего.",
  "Why does this need reviewing?": "Почему требуется пересмотр?",
  "{name} asked for a review of this decision. It stays in force until the approvers answer.": "{name} запросил(а) пересмотр этого решения. Оно остаётся в силе до ответа согласующих.",
  "%s asked you to review this decision": "%s попросил(а) вас пересмотреть это решение",
  "You asked for a review — it is with the approvers": "Вы запросили пересмотр — решение у согласующих",
  "Review · %s": "Пересмотр · %s",
  "Approver keeps or archives": "Согласующий оставляет в силе или архивирует",
  "That review could not be completed.": "Не удалось завершить этот пересмотр.",
  "Review period (months)": "Период пересмотра (месяцев)",
  "The approvers get a task two weeks before a decision is due for review. 0 means no review.": "Согласующие получают задачу за две недели до срока пересмотра решения. Значение 0 означает отсутствие пересмотра.",
  "Archived decisions are never reviewed.": "Архивные решения никогда не пересматриваются.",
  "Superseded and archived decisions are kept here. Read-only, no approvers, no review.": "Здесь хранятся заменённые и архивные решения. Только чтение, без согласующих и пересмотра.",
  "a decision": "решение",
  "{actor} asked for a review of a decision": "{actor} запросил(а) пересмотр решения",
  "%s asked for a review of a decision": "%s запросил(а) пересмотр решения",
  "%1$s (%2$s). You are an approver for it — the review is in My Work.": "%1$s (%2$s). Вы являетесь согласующим — пересмотр находится в разделе «Моя работа».",
  "%s. You are an approver for it — the review is in My Work.": "%s. Вы являетесь согласующим — пересмотр находится в разделе «Моя работа».",
  "A decision is due for review": "Наступает срок пересмотра решения",
  "%1$s — due %2$s. Keep it or archive it from My Work.": "%1$s — срок %2$s. Оставьте в силе или архивируйте через раздел «Моя работа».",
  "%s — keep it or archive it from My Work.": "%s — оставьте в силе или архивируйте через раздел «Моя работа».",
