  "{name} was removed": "{name} — удалено",
  "Add {name}": "Добавить {name}",
  "A sub-team cannot answer service requests. Use its main team instead.": "Вложенная команда не может обрабатывать заявки на услуги. Используйте её основную команду.",
  "Give part of this team its own space": "Предоставить части команды отдельное пространство",
  "A sub-team has its own members, files and modules — picked from this team and managed from here. You can invite people from outside it too.": "У вложенной команды свои участники, файлы и модули: состав выбирается из этой команды, а управление выполняется здесь. Также можно приглашать людей извне.",
  "Sub-teams are part of a paid plan. Ask your Nextcloud administrator about adding them.": "Вложенные команды входят в платный план. Обратитесь к администратору Nextcloud по поводу их подключения.",
  "Your Nextcloud administrator has switched sub-teams off for this instance.": "Администратор Nextcloud отключил вложенные команды на этом экземпляре.",
  "Apply template and policy": "Применить шаблон и политику",
  "Could not be changed: {apps}": "Не удалось изменить: {apps}",
  "Could not change the template or the policy": "Не удалось изменить шаблон или политику",
  "Left in place, because removing it would take the contents with it: {apps}": "Оставлено на месте, поскольку удаление уничтожило бы содержимое: {apps}",
  "Switched off: {apps}": "Отключено: {apps}",
  "Switched on: {apps}": "Включено: {apps}",
  "Switching to {template} switches off {apps}, and what those hold is deleted for good. The files folder and everything in it stays.": "При переходе на {template} отключаются {apps}, а их содержимое удаляется безвозвратно. Папка файлов и всё в ней сохраняются.",
  "The policy decides what this sub-team may do. A Nextcloud administrator defines the ones on offer.": "Политика определяет разрешённые действия этой вложенной команды. Доступные политики задаёт администратор Nextcloud.",
  "Governed by the {policy} policy": "Управляется политикой {policy}",
  "Leave it empty for a sub-team that does not expire.": "Оставьте пустым для вложенной команды без срока действия.",
  "Only Collaboration and Project teams can have an expiration date.": "Срок действия доступен только командам совместной работы и проектов.",
  "Converting team folders to team spaces is paused in this version.": "Преобразование папок команд в пространства команд приостановлено в этой версии.",
  "Cannot delete: in use by {n} entry": "Нельзя удалить: используется в записях ({n})",
  "Cannot delete: status type is in use by {n} entry": "Нельзя удалить: тип статуса используется в записях ({n})",
