  "What is missing": "Чего не хватает",
  "The file is written anyway — it is a faithful picture of what is on this server. A row that cannot be imported again is reported when you try, and the other rows are unaffected.": "Файл всё равно будет записан: он точно отражает содержимое сервера. При попытке повторного импорта неподходящая строка будет отмечена; остальные строки не затрагиваются.",
  "The file lists the account names of every member of every exported team. Downloading one is recorded in the audit log, per team.": "Файл содержит имена учётных записей всех участников экспортируемых команд. Скачивание фиксируется в журнале аудита отдельно для каждой команды.",
